function groupBy<T>(arr: T[], key: keyof T): Map<T[keyof T], T[]> {
  const m = new Map<T[keyof T], T[]>();
  for (const item of arr) {
    const k = item[key];
    if (!m.has(k)) m.set(k, []);
    m.get(k)!.push(item);
  }
  return m;
}

