function flatten(arr: any[]): any[] {
  return arr.reduce((acc, val) =>
    Array.isArray(val) ? [...acc, ...flatten(val)] : [...acc, val], []);
}

function tiefe(obj: any): number {
  if (typeof obj !== "object" || obj === null) return 0;
  return 1 + Math.max(...Object.values(obj).map(tiefe));
}

function binarySearch(arr: number[], ziel: number, lo = 0, hi = arr.length - 1): number {
  if (lo > hi) return -1;
  const mid = Math.floor((lo + hi) / 2);
  if (arr[mid] === ziel) return mid;
  if (arr[mid] < ziel) return binarySearch(arr, ziel, ___, hi);
  return binarySearch(arr, ziel, lo, mid - 1);
}

function fib(n: number, memo: Map<number,number> = new Map()): number {
  if (n <= 1) return n;
  if (memo.has(n)) return memo.get(n)!;
  const result = fib(n-1, memo) + fib(n-2, memo);
  memo.set(n, result);
  return result;
}

