function* zip<T, U>(a: Iterable<T>, b: Iterable<U>): Generator<[T, U]> {
  const iterA = a[Symbol.iterator]();
  const iterB = b[Symbol.iterator]();
  while (true) {
    const ra = iterA.next();
    const rb = iterB.next();
    if (ra.done || rb.done) break;
    yield [ra.value, rb.value];
  }
}
