async function* paginate<T>(
  fetcher: (page: number) => Promise<T[]>,
  pageSize: number
): AsyncGenerator<T[]> {
  let page = 0;
  while (true) {
    const results = await fetcher(page++);
    if (results.length === 0) break;
    yield results;
    if (results.length < pageSize) break;
  }
}

