class Maybe<T> {
  private constructor(private readonly value: T | null) {}
  static of<T>(value: T | null): Maybe<T> { return new Maybe(value); }
  isNothing(): boolean { return this.value === null; }
  map<U>(f: (x: T) => U): Maybe<U> {
    return this.isNothing() ? Maybe.of<U>(null) : Maybe.of(f(this.value!));
  }
  getOrElse(def: T): T { return this.isNothing() ? def : this.value!; }
}

type Result<T, E> =
  | { readonly kind: "ok"; readonly value: T }
  | { readonly kind: "err"; readonly error: E };

const ok = <T>(value: T): Result<T, never> => ({ kind: "ok", value });
const err = <E>(error: E): Result<never, E> => ({ kind: "err", error });

function divide(a: number, b: number): Result<number, string> {
  return b === 0 ? err("Division durch 0") : ok(a / b);
}

class Result<T, E> {
  private constructor(
    private readonly _ok: T | undefined,
    private readonly _err: E | undefined,
    private readonly _isOk: boolean
  ) {}

  map<U>(f: (x: T) => U): Result<U, E> {
    return this._isOk
      ? Result.ok(f(this._ok as T))
      : Result.___(this._err as E);
  }
}

type Task<T> = () => Promise<T>;

const mapTask = <T, U>(task: Task<T>, f: (x: T) => U): Task<U> =>
  () => task().then(f);

const chainTask = <T, U>(task: Task<T>, f: (x: T) => Task<U>): Task<U> =>
  () => task().then(x => f(x)());

type IO<T> = {
  readonly run: () => T;
  map: <U>(f: (x: T) => U) => IO<U>;
  flatMap: <U>(f: (x: T) => IO<U>) => IO<U>;
};

const readLine: IO<string> = {
  run: () => prompt("Eingabe:") ?? "",
  map: f => ({ ...readLine, run: () => f(readLine.run()) }),
  flatMap: f => ({ ...readLine, run: () => f(readLine.run()).run() }),
};

