function chain<T, E, U>(
  f: (x: T) => Result<U, E>
): (r: Result<T, E>) => Result<U, E> {
  return r => r.kind === "ok" ? ___(r.value) : r;
}

type Free<F, A> =
  | { type: "pure"; value: A }
  | { type: "suspend"; effect: F; next: (x: any) => Free<F, A> };

const tryCatch = <T>(f: () => T): Result<T, Error> => {
  try {
    return { kind: "ok", value: f() };
  } catch (e) {
    return { kind: "err", error: e instanceof Error ? e : new Error(String(e)) };
  }
};

