class Validatable {
  [key: string]: unknown;
}
function validate<T extends Validatable>(cls: new () => T) {
  return new Proxy(new cls(), {
    set(target, prop, value) {
      const rules = Reflect.getMetadata("validate", target, prop as string);
      if (rules) rules.forEach((r: Function) => r(value));
      target[prop as string] = value;
      return true;
    }
  });
}

