class EventStore {
  private events: DomainEvent[] = [];

  append(event: DomainEvent): void { this.events.push(event); }

  getEvents(aggregateId: string): DomainEvent[] {
    return this.events.filter(e => e.aggregateId === aggregateId);
  }

  rebuild<T>(aggregateId: string, initial: T, apply: (state: T, event: DomainEvent) => T): T {
    return this.getEvents(aggregateId).reduce(apply, initial);
  }
}

// Clean Architecture Layers
// Entities → Use Cases → Interface Adapters → Frameworks

// Entity (innerste Schicht)
class Money {
  constructor(readonly amount: number, readonly currency: string) {}
  add(other: Money): Money {
    if (this.currency !== other.currency) throw new Error("Verschiedene Währungen");
    return new Money(this.amount + other.amount, this.currency);
  }
}

class Container {
  private bindings = new Map<symbol, () => unknown>();

  bind<T>(token: symbol, factory: () => T): void {
    this.bindings.set(token, factory);
  }

  resolve<T>(token: ___): T {
    const factory = this.bindings.get(token);
    if (!factory) throw new Error(`Nicht gebunden: ${String(token)}`);
    return factory() as T;
  }
}

interface Saga<State, Event> {
  initialState: State;
  transition(state: State, event: Event): State;
  sideEffects(state: State, event: Event): SideEffect[];
}

type SideEffect =
  | { type: "SEND_EMAIL"; to: string; body: string }
  | { type: "PUBLISH_EVENT"; event: DomainEvent }
  | { type: "CALL_API"; url: string };

type AggregateRoot<T extends DomainEvent> = {
  readonly id: string;
  readonly version: number;
  readonly uncommittedEvents: readonly T[];
  apply(event: T): AggregateRoot<T>;
  clearEvents(): AggregateRoot<T>;
};

function createOrder(id: string): AggregateRoot<OrderEvent> {
  return {
    id, version: 0,
    uncommittedEvents: [{ type: "ORDER_CREATED", orderId: id }],
    apply: event => ({ ...this, version: this.version + 1 }),
    clearEvents: () => ({ ...this, uncommittedEvents: [] }),
  } as AggregateRoot<OrderEvent>;
}

